const char *osm_str(enum osm_str_id id)
{
    int lang = global_settings.osm_language;
    if ((unsigned)lang >= OSM_LANG_COUNT)
        lang = OSM_LANG_ENGLISH;
    return (unsigned)id < S_COUNT_ ? strings[lang][id] : "";
}
